class CresaApp extends StatefulWidget { const CresaApp({super.key}); @override State<CresaApp> createState() => _CresaAppState(); }
class _CresaAppState extends State<CresaApp> {
  final api = CresaApi(httpClient());
  final session = SessionStore();
  String? token; AuthUser? user; bool ready = false;
  @override void initState() { super.initState(); session.read().then((saved) { if (!mounted) return; setState(() { token = saved.$1; user = saved.$2; ready = true; }); }); }
  @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'Cresa E-library', theme: CresaTheme.light(), home: !ready ? const Scaffold(body: Center(child: CircularProgressIndicator())) : token == null || user == null ? LoginPage(api: api, session: session, onLogin: (value) => setState(() { token = value.$1; user = value.$2; })) : HomeShell(api: api, session: session, token: token!, user: user!, onLogout: () => setState(() { token = null; user = null; }));
}

http.Client httpClient() => http.Client();

