class HomeShell extends StatefulWidget { const HomeShell({super.key, required this.api, required this.session, required this.token, required this.user, required this.onLogout}); final CresaApi api; final SessionStore session; final String token; final AuthUser user; final VoidCallback onLogout; @override State<HomeShell> createState() => _HomeShellState(); }
class _HomeShellState extends State<HomeShell> {
  int index = 0; int unread = 0; Timer? timer;
  final titles = const ['Overview', 'My Library', 'Discover', 'Community', 'Settings'];
  @override void initState() { super.initState(); refreshNotifications(); timer = Timer.periodic(const Duration(seconds: 15), (_) => refreshNotifications()); }
  @override void dispose() { timer?.cancel(); super.dispose(); }
  Future<void> refreshNotifications() async { final result = await widget.api.notifications(widget.token); if (mounted && result.ok) setState(() => unread = result.data!.where((item) => item.readAt == null).length); }
  void openPage(int value) { setState(() => index = value); if (value == 3) { widget.api.readNotifications(widget.token); setState(() => unread = 0); } }
  @override Widget build(BuildContext context) { final pages = [OverviewPage(user: widget.user, onOpen: openPage), LibraryPage(api: widget.api, token: widget.token), const DiscoverPage(), CommunityPage(api: widget.api, token: widget.token, user: widget.user), SettingsPage(api: widget.api, token: widget.token, user: widget.user, onLogout: widget.onLogout)]; return Scaffold(appBar: AppBar(title: Row(children: [const CresaLogo(size: 30), const SizedBox(width: 9), Text(titles[index], style: const TextStyle(fontWeight: FontWeight.w800))]), actions: [IconButton(onPressed: () => showNotifications(context), icon: Badge(isLabelVisible: unread > 0, label: Text('$unread'), child: const Icon(Icons.notifications_none_rounded))), const SizedBox(width: 8)]), body: IndexedStack(index: index, children: pages), floatingActionButton: FloatingActionButton.extended(onPressed: () => showModalBottomSheet(context: context, isScrollControlled: true, showDragHandle: true, builder: (_) => CresaBotSheet(api: widget.api, token: widget.token)), icon: const Icon(Icons.auto_awesome_rounded), label: const Text('CresaBot')), bottomNavigationBar: NavigationBar(selectedIndex: index, onDestinationSelected: openPage, destinations: [const NavigationDestination(icon: Icon(Icons.grid_view_rounded), label: 'Overview'), const NavigationDestination(icon: Icon(Icons.menu_book_rounded), label: 'Library'), const NavigationDestination(icon: Icon(Icons.explore_outlined), label: 'Discover'), NavigationDestination(icon: Badge(isLabelVisible: unread > 0, label: Text('$unread'), child: const Icon(Icons.groups_rounded)), label: 'Community'), const NavigationDestination(icon: Icon(Icons.settings_outlined), label: 'Settings')]) ); }
  Future<void> showNotifications(BuildContext context) async { final result = await widget.api.notifications(widget.token); if (!context.mounted) return; showModalBottomSheet(context: context, showDragHandle: true, builder: (_) => SafeArea(child: result.ok && result.data!.isNotEmpty ? ListView(padding: const EdgeInsets.all(18), children: [Text('Notifications', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w800)), const SizedBox(height: 12), ...result.data!.map((item) => ListTile(leading: Icon(item.type == 'reaction' ? Icons.favorite_rounded : item.type == 'comment' ? Icons.chat_bubble_rounded : Icons.alternate_email_rounded, color: CresaTheme.blue), title: Text(item.message), subtitle: Text(item.createdAt.toLocal().toString())))]): const Padding(padding: EdgeInsets.all(30), child: Text('No notifications yet.')))); }
}

