  Widget stat(BuildContext context, String label, String value) => CresaCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(label, style: const TextStyle(color: CresaTheme.muted, fontSize: 11)), const SizedBox(height: 7), Text(value, style: Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.w800, color: CresaTheme.ink))]));
